import {
  encodeAbiParameters,
  getCreate2Address,
  isAddress,
  isHex,
  keccak256,
  toHex,
  type Address,
  type Hex,
} from "viem";
import { SdkError } from "./errors.js";

export const LAUNCH_TOKEN_TOTAL_SUPPLY = 1_000_000_000n * 10n ** 18n;

/**
 * Reviewed LaunchToken creation code from the verified gen-12 deployment.
 *
 * CREATE2 includes the complete init code in its address derivation, so clients need this
 * immutable bytecode to predict vanity launch addresses without an RPC simulation.
 * Provenance: Robinhood Chain mainnet token 0x0148b4ef4c5fe04ce8c9d5405c91b4dca821b10c.
 */
const LAUNCH_TOKEN_CREATION_CODE: Hex =
  "";

export interface PredictLaunchTokenAddressParameters {
  launchpad: Address;
  creator: Address;
  name: string;
  symbol: string;
  metadataUri: string;
  salt: Hex;
}

export interface MineLaunchTokenVanitySaltParameters
  extends Omit<PredictLaunchTokenAddressParameters, "salt"> {
  /** One through eight hexadecimal nibbles, without a 0x prefix. */
  suffix: string;
  /** First candidate to inspect. Defaults to 1. */
  startSalt?: bigint;
  /** Bounded work for this batch. Defaults to 100,000 attempts. */
  maxAttempts?: number;
}

export interface LaunchTokenVanityResult {
  address: Address;
  salt: Hex;
  attempts: number;
}

/**
 * Predicts the token deployed by Launchpad.createLaunchVanity for exact launch metadata.
 *
 * The Launchpad namespaces the caller salt with msg.sender before passing it to CREATE2.
 * Changing creator, name, symbol, metadata URI, salt, or Launchpad changes the result.
 */
export function predictLaunchTokenAddress(
  parameters: PredictLaunchTokenAddressParameters,
): Address {
  assertBytes32(parameters.salt, "salt");
  if (BigInt(parameters.salt) === 0n) {
    throw invalidArgument("salt", "nonzero bytes32", parameters.salt);
  }
  const context = createPredictionContext(parameters);
  return predictFromContext(context, parameters.salt);
}

/**
 * Searches a deterministic, bounded salt range for a vanity token suffix.
 *
 * This function performs CPU work only. Browser consumers should call it in a Web Worker.
 * Return null to continue with another batch beginning after the attempted range.
 */
export function mineLaunchTokenVanitySalt(
  parameters: MineLaunchTokenVanitySaltParameters,
): LaunchTokenVanityResult | null {
  const suffix = normalizeSuffix(parameters.suffix);
  const startSalt = parameters.startSalt ?? 1n;
  const maxAttempts = parameters.maxAttempts ?? 100_000;
  if (startSalt <= 0n || startSalt >= 1n << 256n) {
    throw invalidArgument("startSalt", "integer from 1 through 2^256 - 1", startSalt);
  }
  if (!Number.isSafeInteger(maxAttempts) || maxAttempts <= 0) {
    throw invalidArgument("maxAttempts", "positive safe integer", maxAttempts);
  }
  if (startSalt + BigInt(maxAttempts) > 1n << 256n) {
    throw invalidArgument("maxAttempts", "candidate range within bytes32", maxAttempts);
  }
  const context = createPredictionContext(parameters);

  for (let offset = 0; offset < maxAttempts; offset += 1) {
    const salt = toHex(startSalt + BigInt(offset), { size: 32 });
    const address = predictFromContext(context, salt);
    if (address.toLowerCase().endsWith(suffix)) {
      return { address, salt, attempts: offset + 1 };
    }
  }
  return null;
}

interface PredictionContext {
  launchpad: Address;
  creator: Address;
  bytecodeHash: Hex;
}

function createPredictionContext(
  parameters: Omit<PredictLaunchTokenAddressParameters, "salt">,
): PredictionContext {
  assertAddress(parameters.launchpad, "launchpad");
  assertAddress(parameters.creator, "creator");
  const constructorArguments = encodeAbiParameters(
    [
      { type: "string" },
      { type: "string" },
      { type: "uint256" },
      { type: "address" },
      { type: "string" },
    ],
    [
      parameters.name,
      parameters.symbol,
      LAUNCH_TOKEN_TOTAL_SUPPLY,
      parameters.launchpad,
      parameters.metadataUri,
    ],
  );
  return {
    launchpad: parameters.launchpad,
    creator: parameters.creator,
    bytecodeHash: keccak256(`${LAUNCH_TOKEN_CREATION_CODE}${constructorArguments.slice(2)}`),
  };
}

function predictFromContext(context: PredictionContext, salt: Hex): Address {
  const finalSalt = keccak256(
    encodeAbiParameters(
      [{ type: "address" }, { type: "bytes32" }],
      [context.creator, salt],
    ),
  );
  return getCreate2Address({
    from: context.launchpad,
    salt: finalSalt,
    bytecodeHash: context.bytecodeHash,
  });
}

function normalizeSuffix(suffix: string): string {
  const normalized = suffix.toLowerCase();
  if (!/^[0-9a-f]{1,8}$/.test(normalized)) {
    throw invalidArgument("suffix", "one through eight hexadecimal characters without 0x", suffix);
  }
  return normalized;
}

function assertAddress(value: Address, path: string): void {
  if (!isAddress(value)) {
    throw new SdkError("INVALID_ADDRESS", `${path} must be an EVM address`, {
      path,
      expected: "20-byte EVM address",
      actual: value,
    });
  }
}

function assertBytes32(value: Hex, path: string): void {
  if (!isHex(value) || value.length !== 66) {
    throw invalidArgument(path, "32-byte hex value", value);
  }
}

function invalidArgument(path: string, expected: string, actual: unknown): SdkError {
  return new SdkError("INVALID_ARGUMENT", `${path} must be ${expected}`, {
    path,
    expected,
    actual: String(actual),
  });
}
